//! 📄️ Dense page custody initializes only the live prefix and preserves real transfer ordinals.
use semio_framework_job_payload::*;
use semio_framework_trace::{OperationId,Generation,observe_heap_allocations_on_this_thread as observe};
#[path="../../🧪️testing/🦀️.rs"]
mod testing;
use testing::PayloadCase;
fn law()->serde_json::Value{let row:serde_json::Value=serde_json::from_str(include_str!("case.json")).unwrap();let schema:serde_json::Value=serde_json::from_str(include_str!("case.schema.json")).unwrap();for(k,v)in row.as_object().unwrap(){assert_eq!(&schema["properties"][k]["const"],v);}row}
fn close_case(case:PayloadCase){let(ledger,mut case)=case.into_ledger();let mut ledger=Some(ledger);case.close_ledger(&mut ledger);assert!(ledger.is_none());let(_,heap)=observe(||drop(case));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
#[test]
fn actual_payload_header_birth_uses_one_paid_turn_and_zero_unused_page_rows(){
 let row=law();let mut case=PayloadCase::new(OperationId(99711),Generation(3));let mut b=RetainedPayloadBuilder::new(JobPayloadStream::CommitOutput);
 for grant in [RetainedCloneGrant{maximum_items:0,maximum_depth:1,..Default::default()},RetainedCloneGrant{maximum_items:1,maximum_depth:0,..Default::default()}]{let(step,heap)=observe(||case.step(grant,|cx|{let turn=b.advance_initialization(cx);assert_eq!(turn.work,0);turn}));assert_eq!(step.progress(),Default::default());assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert!(b.terminal_is_empty());}
 let(step,heap)=observe(||case.step(PayloadCase::exact(b.initialization_demand()),|cx|{let turn=b.advance_initialization(cx);assert_eq!(turn.work,u128::from(row["headerInitializationTurns"].as_u64().unwrap()));turn}));assert!(matches!(step,RetainedCloneStep::Complete(_)));assert_eq!(step.progress(),RetainedCloneProgress{copied_items:1,..Default::default()});assert!(!heap.overflowed);assert_eq!(serde_json::to_value([heap.requested_bytes,heap.released_bytes]).unwrap(),row["headerHeap"]);assert!(b.is_initialized());let payload=b.original().unwrap();assert_eq!(payload.page_count(),row["emptyLivePages"].as_u64().unwrap()as usize);assert_eq!(payload.allocated_capacity_bytes(),0);for index in [0,255,256,usize::MAX]{assert!(payload.page(index).is_none());assert!(payload.page_capacity_bytes(index).is_none());}
 case.step(PayloadCase::exact(b.initialization_demand()),|cx|{let turn=b.advance_initialization(cx);assert_eq!(turn.work,0);turn});case.close(b.retirement_demands().unwrap(),b.retirement_work().unwrap(),|effect|b.close_step(effect));assert!(b.terminal_is_empty());let(_,heap)=observe(||drop(b));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close_case(case);
}
#[test]
fn actual_dense_page_reader_overflow_and_last_page_transfer_match_neutral_ordinals(){
 let row=law();for count in row["pageCases"].as_array().unwrap(){let count=count.as_u64().unwrap()as usize;let mut case=PayloadCase::new(OperationId(99720+count as u64),Generation(3));let mut b=case.initialize(JobPayloadStream::CommitOutput);let expected:Vec<u8>=(0..count).map(|i|i as u8).collect();let mut pointers=Vec::new();
  for byte in &expected{case.page(&mut b,std::slice::from_ref(byte));let p=b.original().unwrap();assert_eq!(p.page_count(),pointers.len()+1);pointers.push(p.page(pointers.len()).unwrap().as_ptr());}
  if count==row["maximumPages"].as_u64().unwrap()as usize{let mut source=Some(case.source(1));let pointer=source.as_ref().unwrap().backing_identity();case.step(PayloadCase::exact(b.original_page_admission_demand(&source).unwrap()),|cx|b.accept_original_page(&mut source,cx));assert!(source.is_none());assert_eq!(b.incoming_backing_identity(),Some(pointer));let(result,_)=case.apply(RetainedCloneGrant{maximum_items:1,maximum_depth:128,..Default::default()},|cx|{let turn=b.accept_original_page(&mut source,cx);let p=turn.result.as_ref().map_or_else(|e|e.retained_progress(),|s|s.progress());RetainedWorkOutcome{result:Ok((turn.result,p)),work:turn.work}},|(_,p)|*p);assert!(result.is_err());assert_eq!(b.incoming_backing_identity(),Some(pointer));let(step,heap)=semio_framework_value_testing_allocator::observe_retirement_allocations(||case.close(b.retirement_demands().unwrap(),b.retirement_work().unwrap(),|effect|b.close_step(effect)));assert_eq!(step.progress().released_bytes,1);assert_eq!(heap,(0,1));assert_eq!(b.original().unwrap().page_count(),count);}
  let mut payload=case.finish(&mut b);let mut reader=payload.reader();let mut actual=Vec::new();while let Some(bytes)=reader.read_page(1,1){actual.extend_from_slice(bytes);}assert!(reader.terminal_is_empty());assert_eq!(serde_json::to_value(actual).unwrap(),serde_json::to_value(&expected).unwrap());assert!(payload.page(count).is_none());let identity=payload.payload_authority_identity();
  for index in (0..count).rev(){let mut transfer=None;for _ in 0..2{if transfer.as_ref().is_some_and(RetainedJobPageTransfer::is_ready){break}case.close(payload.original_page_transfer_demand(&transfer).unwrap(),1,|effect|payload.transfer_last_original_page(&mut transfer,effect));}let mut transfer=transfer.unwrap();assert!(transfer.is_ready());assert_eq!(transfer.original_index(),index);assert_eq!(transfer.page_identity(),Some(pointers[index]));assert_eq!(transfer.ledger_identity(),identity);assert_eq!(transfer.bytes(),Some(std::slice::from_ref(&expected[index])));assert_eq!(payload.page_count(),index);assert!(payload.page(index).is_none());while !transfer.terminal_is_empty(){case.close(transfer.retirement_demands(),1,|effect|transfer.close_step(effect));}let(_,heap)=observe(||drop(transfer));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));}
  assert!(payload.terminal_is_empty());let(_,heap)=observe(||drop((payload,b)));assert!(!heap.overflowed);assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));close_case(case);
 }
}
